/**
 * GeoParquet, YAML only (0.9, ml-cnv.4) — browser verification, which is
 * also the demo (examples/verification/cloud-native/geoparquet.html).
 *
 * @remarks
 * Fixtures: synthetic, CC0, generated by scripts/fixtures/cloud-native.py
 * into docs/public/gallery-assets/cloud-native/, served by e2e/server.mjs
 * with HTTP range support (and its /norange/, /nocors/,
 * /norange/oversize/<MB>/ variants for the failure cases). The base path,
 * story and CDN cases ride on the shared pages in e2e/cloud-native.spec.ts.
 * Runs on every maplibre-gl leg of the CI matrix (4/5/6).
 */
import { test, expect, type Page } from "@playwright/test";

/** Fail on page errors and off-origin requests (hermeticity). */
async function guard(page: Page): Promise<string[]> {
  const errors: string[] = [];
  page.on("pageerror", (e) => errors.push(e.message));
  await page.route("**/*", (route) => {
    const url = route.request().url();
    if (/^https?:\/\/(localhost|127\.0\.0\.1)[:/]/.test(url) || /^(data|blob):/.test(url)) return route.continue();
    errors.push(`external request (suite must stay hermetic): ${url}`);
    return route.abort();
  });
  return errors;
}

/** Record every response for a file name: status, the Range sent, and the body size. */
function recordRequests(page: Page, name: RegExp) {
  const seen: { url: string; status: number; range: string | undefined }[] = [];
  page.on("response", (r) => {
    if (name.test(r.url())) seen.push({ url: r.url(), status: r.status(), range: r.request().headers()["range"] });
  });
  return seen;
}

/** Wait until a map element's source has rendered features. */
async function waitForFeatures(page: Page, mapId: string, source: string) {
  await page.waitForFunction(
    ({ mapId, source }) => {
      const map = (document.getElementById(mapId) as any)?.getMap?.();
      return Boolean(map && map.getSource(source) && map.querySourceFeatures(source).length > 0);
    },
    { mapId, source },
    { timeout: 45_000 }
  );
}

const OPEN = async (page: Page, ...ids: string[]) => {
  await page.goto("/examples/verification/cloud-native/geoparquet.html", { waitUntil: "domcontentloaded" });
  for (const id of ids) await page.evaluate((id) => (document.getElementById(id) as any).mapReady(), id);
};

test.describe("GeoParquet with no page JavaScript", () => {
  test("whole file: classify, popup, fitTo framed — and only the referenced columns read", async ({ page }) => {
    const errors = await guard(page);
    const districts = recordRequests(page, /localhost:\d+\/gallery-assets\/cloud-native\/districts\.parquet$/);
    await OPEN(page, "whole");
    await waitForFeatures(page, "whole", "districts");
    await page.waitForFunction(() => {
      const map = (document.getElementById("whole") as any).getMap();
      const color = map.getPaintProperty("districts", "fill-color");
      return !map.isMoving() && Array.isArray(color) && JSON.stringify(color).includes("population");
    });
    const state = await page.evaluate(() => {
      const map = (document.getElementById("whole") as any).getMap();
      const features = map.querySourceFeatures("districts");
      return {
        names: new Set(features.map((f: any) => f.properties.name)).size,
        keys: Object.keys(features[0].properties).sort(),
        center: map.getCenter().toArray(),
        zoom: map.getZoom(),
        color: JSON.stringify(map.getPaintProperty("districts", "fill-color")),
        points: map.querySourceFeatures("points").length,
        notice: document.querySelector("#whole .ml-map-notice")?.textContent ?? null,
      };
    });
    expect(state.names).toBe(48);
    // Column projection: the popup's properties and the classify field (which
    // nothing else names: classify reaches the renderer compiled into the
    // layer's metadata) — and nothing else in the file.
    expect(state.keys).toEqual(["category", "name", "population"]);
    // fitTo framed the decoded districts (the document says [0, 0] z1).
    expect(Math.abs(state.center[0] - 10.2)).toBeLessThan(0.05);
    expect(Math.abs(state.center[1] - 42.15)).toBeLessThan(0.05);
    expect(state.zoom).toBeGreaterThan(9);
    expect(state.color).toMatch(/"step"/);
    // Below the viewport source's minzoom (11), nothing is read for it.
    expect(state.points).toBe(0);
    expect(state.notice).toBeNull();
    // One suffix-range request opens the file (no HEAD) — and, this small, reads all of it.
    expect(districts.length).toBe(1);
    expect(districts[0]!.range).toBe("bytes=-524288");
    expect(districts[0]!.status).toBe(206);

    // A district's popup, from the GeoParquet feature's properties.
    const at = await page.evaluate(() => {
      const map = (document.getElementById("whole") as any).getMap();
      const ring = map.querySourceFeatures("districts")[0].geometry.coordinates[0];
      const xs = ring.map((c: number[]) => c[0]);
      const ys = ring.map((c: number[]) => c[1]);
      const p = map.project([(Math.min(...xs) + Math.max(...xs)) / 2, (Math.min(...ys) + Math.max(...ys)) / 2]);
      const rect = map.getCanvas().getBoundingClientRect();
      return { x: rect.left + p.x, y: rect.top + p.y };
    });
    await page.mouse.click(at.x, at.y);
    await expect(page.locator("#whole .maplibregl-popup")).toContainText("District");
    await expect(page.locator("#whole .maplibregl-popup")).toContainText("Category: ");
    await page.screenshot({ path: "e2e/results/geoparquet_whole.png" });
    expect(errors).toEqual([]);
  });

  test("load: viewport reads only the features in view, and re-reads on pan", async ({ page }) => {
    const errors = await guard(page);
    const points = recordRequests(page, /localhost:\d+\/gallery-assets\/cloud-native\/points\.parquet$/);
    await OPEN(page, "whole");
    await waitForFeatures(page, "whole", "districts");
    // Positions identify the points (the document reads only `kind` from them).
    const ids = () =>
      page.evaluate(() => [
        ...new Set(
          (document.getElementById("whole") as any)
            .getMap()
            .querySourceFeatures("points")
            .map((f: any) => f.geometry.coordinates.join(","))
        ),
      ]);

    await page.evaluate(() => (document.getElementById("whole") as any).getMap().jumpTo({ center: [10.05, 42.04], zoom: 12.5 }));
    await waitForFeatures(page, "whole", "points");
    const first = await ids();
    expect(first.length).toBeGreaterThan(0);
    expect(first.length).toBeLessThan(400);
    const afterFirst = points.length;

    await page.evaluate(() => (document.getElementById("whole") as any).getMap().jumpTo({ center: [10.36, 42.26], zoom: 12.5 }));
    await page.waitForFunction(
      (before) => {
        const map = (document.getElementById("whole") as any).getMap();
        const now = map.querySourceFeatures("points").map((f: any) => f.geometry.coordinates.join(","));
        return now.length > 0 && !now.some((id: string) => before.includes(id));
      },
      first,
      { timeout: 30_000 }
    );
    // This file is smaller than the first (footer) read, so that one range
    // request holds all of it: each re-read filters row groups in memory.
    // (Skipping row groups over the network is measured in the unit suite,
    // tests/formats/geoparquet.test.ts.)
    expect(afterFirst).toBe(1);
    expect(points).toHaveLength(1);
    expect(points[0]!.range).toBe("bytes=-524288");
    expect(points[0]!.status).toBe(206);
    // Viewport features carry only what the document reads from them.
    const keys = await page.evaluate(() =>
      Object.keys((document.getElementById("whole") as any).getMap().querySourceFeatures("points")[0].properties)
    );
    expect(keys).toEqual(["kind"]);
    await expect(page.locator("#whole .ml-map-notice")).toHaveCount(0);
    await page.screenshot({ path: "e2e/results/geoparquet_viewport.png" });
    expect(errors).toEqual([]);
  });

  test("a v2 document: runtime: format, load and columns; a brotli file decodes too", async ({ page }) => {
    const errors = await guard(page);
    await OPEN(page, "v2");
    await waitForFeatures(page, "v2", "districts");
    await waitForFeatures(page, "v2", "brotli");
    const state = await page.evaluate(() => {
      const map = (document.getElementById("v2") as any).getMap();
      return {
        districts: new Set(
          map.querySourceFeatures("districts").map((f: any) => JSON.stringify(f.geometry.coordinates[0][0]))
        ).size,
        districtKeys: Object.keys(map.querySourceFeatures("districts")[0].properties),
        brotli: new Set(map.querySourceFeatures("brotli").map((f: any) => f.geometry.coordinates.join(","))).size,
        points: map.querySourceFeatures("points").length,
        spec: map.getStyle().sources.points,
      };
    });
    expect(state.districts).toBeGreaterThan(40);
    // Only the column this document reads from the districts (its fill colour).
    expect(state.districtKeys).toEqual(["category"]);
    expect(state.brotli).toBeGreaterThan(300);
    expect(state.points).toBe(0); // below minzoom 11
    // Our keys never reach MapLibre.
    expect(JSON.stringify(state.spec)).not.toMatch(/"columns"|"load"|"format"/);
    await expect(page.locator("#v2 .ml-map-notice")).toHaveCount(0);
    expect(errors).toEqual([]);
  });

  test("every GeoParquet failure is explained on the map in plain words", async ({ page }) => {
    const errors = await guard(page);
    await OPEN(page, "failures", "hosting", "fallbacks");
    let notice = page.locator("#failures .ml-map-notice");
    await expect(notice).toContainText(
      "Layer geoarrow has no data: /gallery-assets/cloud-native/points-geoarrow.parquet stores its geometry as " +
        "GeoArrow (point), which maplibre-yaml doesn't read yet: it reads GeoParquet with WKB geometry. Rewrite it " +
        "with WKB: ogr2ogr -f Parquet -lco GEOMETRY_ENCODING=WKB out.parquet points-geoarrow.parquet"
    );
    await expect(notice).toContainText(
      "Layer mercator has no data: /gallery-assets/cloud-native/districts-3857.parquet is in EPSG:3857; MapLibre " +
        "needs longitude/latitude (EPSG:4326). Reproject it: ogr2ogr -t_srs EPSG:4326 out.parquet districts-3857.parquet."
    );
    await expect(notice).toContainText(
      "Layer plain has no data: /gallery-assets/cloud-native/plain.parquet is a Parquet file but not GeoParquet"
    );
    await expect(notice).toContainText(
      "Layer webpage has no data: /gallery-assets/cloud-native/not-really.parquet isn't a GeoParquet file."
    );
    const fileText = (await notice.textContent()) ?? "";
    notice = page.locator("#hosting .ml-map-notice");
    await expect(notice).toContainText(
      "Data file /gallery-assets/cloud-native/missing.parquet didn't load (404 Not Found), so layer missing has no data."
    );
    await expect(notice).toContainText(
      /Layer blocked has no data: The browser couldn't read http:\/\/127\.0\.0\.1:\d+\/nocors\/gallery-assets\/cloud-native\/districts\.parquet: the server didn't allow this page to load it \(CORS\)/
    );
    await expect(notice).toContainText(
      "Layer nobbox has no data: /gallery-assets/cloud-native/districts-nobbox.parquet has no bbox covering column"
    );
    // A big file on a host without range requests (python -m http.server):
    // refused before its 60 MB body is downloaded.
    await expect(notice).toContainText(
      "Layer norange has no data: /norange/oversize/60/gallery-assets/cloud-native/points.parquet was served " +
        "without range-request support (the server sent the whole file instead of the part asked for)."
    );
    await expect(notice).toContainText("python -m http.server does not — preview locally with npx serve instead.");
    const text = fileText + ((await notice.textContent()) ?? "");
    expect(text).not.toMatch(/and \d+ more/);
    expect(text).not.toMatch(/PAR1|parquet file invalid|Failed to fetch|Unexpected token|not supported yet/i);

    // What must work anyway: a small file on a host without ranges, an unsorted file read by view.
    await waitForFeatures(page, "fallbacks", "norange");
    await waitForFeatures(page, "fallbacks", "unsorted");
    await expect(page.locator("#fallbacks .ml-map-notice")).toHaveCount(0);
    await page.screenshot({ path: "e2e/results/geoparquet_errors.png", fullPage: true });
    expect(errors).toEqual([]);
  });
});
